var totalMoney = function(n) {
    const weeks = Math.floor(n / 7);
    const rem = n % 7;
    const totalWeeks = 28 * weeks + 7 * Math.floor(weeks * (weeks - 1) / 2);
    const remSum = rem * (weeks + 1) + Math.floor(rem * (rem - 1) / 2);
    return totalWeeks + remSum;
};
